insert into public.characters(game_id,name,full_name,profession,rarity)
select yys.id,catalog.name,catalog.name,'式神',catalog.rarity
from yys cross join catalog
on conflict(game_id,name) do update set
  rarity=excluded.rarity,
  profession='式神',
  full_name=coalesce(nullif(public.characters.full_name,''),excluded.full_name),
  updated_at=now();

update public.characters c
set full_name='源雪姬', sex='女', updated_at=now()
from public.games g
where c.game_id=g.id and g.code='YYS' and c.name='雪御前';

insert into public.character_names(id,character_id,lang,name)
select gen_random_uuid(),c.id,'zh',c.name
from public.characters c
join public.games g on g.id=c.game_id
where g.code='YYS'
on conflict(character_id,lang) do update set name=excluded.name,updated_at=now();

commit;
